/**
 * src/lib/graph/graphClient.ts — SOLO SERVER (Route Handlers).
 * Confidential client (client_credentials) con Sites.Selected: il token .default
 * contiene esclusivamente i permessi applicativi consentiti (NO Sites.ReadWrite.All).
 * NB: app registration DISTINTA dalla SPA di src/lib/msalConfig.ts:11-17 (public client).
 * Nessun segreto hardcoded: env server-side (senza prefisso NEXT_PUBLIC_) o Azure Key Vault.
 */
import 'server-only';

const TENANT_ID = process.env.GRAPH_TENANT_ID!;         // es. usltoscananordovest.onmicrosoft.com (ASSUNZIONE DA VERIFICARE)
const CLIENT_ID = process.env.GRAPH_CLIENT_ID!;
const CLIENT_SECRET = process.env.GRAPH_CLIENT_SECRET!;  // Vercel encrypted env / Azure Key Vault reference — MAI in repo
export const SP_SITE_ID = process.env.SP_SITE_ID!;       // GET /sites/toscananordovest.sharepoint.com:/sites/DipartimentoTecnico (una tantum)
export const SP_DRIVE_ID = process.env.SP_DRIVE_ID!;     // drive della libreria "Fascicoli Richieste TS"
export const SP_LIST_ID = process.env.SP_LIST_ID!;       // list id della stessa libreria (per query su colonne)

const GRAPH = 'https://graph.microsoft.com/v1.0';
export { GRAPH };

let cached: { token: string; exp: number } | null = null;

export async function getGraphToken(): Promise<string> {
  if (cached && Date.now() < cached.exp - 60_000) return cached.token;
  const res = await fetch(`https://login.microsoftonline.com/${TENANT_ID}/oauth2/v2.0/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      client_id: CLIENT_ID,
      client_secret: CLIENT_SECRET,
      grant_type: 'client_credentials',
      scope: 'https://graph.microsoft.com/.default',
    }),
  });
  if (!res.ok) throw new Error(`Token Graph fallito: ${res.status} ${await res.text()}`);
  const j = await res.json();
  cached = { token: j.access_token, exp: Date.now() + j.expires_in * 1000 };
  return cached.token;
}

/** fetch verso Graph con gestione throttling: onora Retry-After su 429/503, backoff esponenziale altrimenti. */
export async function graphFetch(url: string, init: RequestInit = {}, maxRetries = 4): Promise<Response> {
  for (let attempt = 0; ; attempt++) {
    const token = await getGraphToken();
    const res = await fetch(url, {
      ...init,
      headers: { ...(init.headers ?? {}), Authorization: `Bearer ${token}` },
    });
    if ((res.status === 429 || res.status === 503 || res.status === 504) && attempt < maxRetries) {
      const retryAfter = Number(res.headers.get('Retry-After'));
      const waitMs = (Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : 2 ** attempt) * 1000;
      await new Promise((r) => setTimeout(r, waitMs));
      continue;
    }
    return res;
  }
}

/**
 * src/app/api/richieste/[id]/documenti/route.ts — POST: upload file nel fascicolo con metadati.
 * Cartella fascicolo = numeroProgressivo (primary column univoca, SETUP_DATAVERSE_TABLES.md:98).
 * Il client invia multipart/form-data: file + campo 'metadati' (JSON derivato da TechnologyRequest).
 * PREREQUISITO: validare il bearer token Entra ID dell'utente (jwks) prima di usare il token app —
 * oggi l'app e' interamente client-side (src/app/ contiene solo layout.tsx e page.tsx), questo
 * Route Handler introduce il primo layer server-side.
 */
import { NextRequest, NextResponse } from 'next/server';
import { GRAPH, SP_SITE_ID, SP_DRIVE_ID, graphFetch } from '@/lib/graph/graphClient';
import { verifyEntraToken } from '@/lib/graph/verifyToken'; // jose + JWKS tenant: aud/iss/exp

interface DocumentoMetadati {
  richiestaId: string;          // TechnologyRequest.id (src/types/index.ts:234)
  numeroProgressivo: string;    // es. "2025-001" (src/types/index.ts:235)
  track?: string;               // trackAssegnato (src/types/index.ts:241)
  stato: string;                // statoCorrente (src/types/index.ts:240)
  unitaOperativa: string;       // src/types/index.ts:249
  dipartimento: string;         // src/types/index.ts:250
  importo?: number;             // budget.valoreStimatoEuro (src/types/index.ts:187)
  cig?: string;                 // ASSUNZIONE DA VERIFICARE: campo non presente in TechnologyRequest
  tipoDocumento: 'MOD01' | 'MOD02' | 'ALLEGATO_TECNICO' | 'PREVENTIVO'
    | 'VERBALE_COMMAZ' | 'PARERE_HTA' | 'ATTO_APPROVAZIONE' | 'REPORT_TRIMESTRALE';
}

export async function POST(req: NextRequest, { params }: { params: { id: string } }) {
  const user = await verifyEntraToken(req.headers.get('authorization'));
  if (!user) return NextResponse.json({ error: 'Non autorizzato' }, { status: 401 });

  const form = await req.formData();
  const file = form.get('file') as File | null;
  const meta = JSON.parse((form.get('metadati') as string) ?? '{}') as DocumentoMetadati;
  if (!file || !meta.numeroProgressivo) {
    return NextResponse.json({ error: 'file o metadati mancanti' }, { status: 400 });
  }

  const folder = encodeURIComponent(meta.numeroProgressivo); // 1 cartella per record ts_richiestes
  const name = encodeURIComponent(file.name.replace(/[#%*:<>?/\\|]/g, '_'));
  const bytes = Buffer.from(await file.arrayBuffer());

  // 1) Upload contenuto. <= 4 MB: PUT diretto; oltre: createUploadSession + chunk da 5-10 MiB.
  let item: { id: string; webUrl: string; size: number };
  if (bytes.length <= 4 * 1024 * 1024) {
    const up = await graphFetch(
      `${GRAPH}/sites/${SP_SITE_ID}/drives/${SP_DRIVE_ID}/root:/${folder}/${name}:/content`,
      { method: 'PUT', headers: { 'Content-Type': 'application/octet-stream' }, body: bytes },
    );
    if (!up.ok) return NextResponse.json({ error: await up.text() }, { status: up.status });
    item = await up.json();
  } else {
    const sess = await graphFetch(
      `${GRAPH}/sites/${SP_SITE_ID}/drives/${SP_DRIVE_ID}/root:/${folder}/${name}:/createUploadSession`,
      { method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ item: { '@microsoft.graph.conflictBehavior': 'rename' } }) },
    );
    const { uploadUrl } = await sess.json();
    const CHUNK = 5 * 1024 * 1024;
    let last: Response | null = null;
    for (let off = 0; off < bytes.length; off += CHUNK) {
      const end = Math.min(off + CHUNK, bytes.length);
      last = await fetch(uploadUrl, { // upload session: niente Authorization header
        method: 'PUT',
        headers: {
          'Content-Length': String(end - off),
          'Content-Range': `bytes ${off}-${end - 1}/${bytes.length}`,
        },
        body: bytes.subarray(off, end),
      });
    }
    if (!last?.ok) return NextResponse.json({ error: 'upload session fallita' }, { status: 502 });
    item = await last.json();
  }

  // 2) Metadati sulle colonne della libreria (vedi mappatura_documentale).
  const patch = await graphFetch(
    `${GRAPH}/sites/${SP_SITE_ID}/drives/${SP_DRIVE_ID}/items/${item.id}/listItem/fields`,
    { method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        tsRichiestaId: params.id,
        tsNumeroProgressivo: meta.numeroProgressivo,
        tsTrack: meta.track ?? '',
        tsStato: meta.stato,
        tsUnitaOperativa: meta.unitaOperativa,
        tsDipartimento: meta.dipartimento,
        tsImporto: meta.importo ?? null,
        tsCIG: meta.cig ?? '',
        tsTipoDocumento: meta.tipoDocumento,
        tsCaricatoDa: user.email,
      }) },
  );
  if (!patch.ok) return NextResponse.json({ error: await patch.text() }, { status: patch.status });

  // 3) Risposta nella forma dell'interfaccia Attachment (src/types/index.ts:359-367):
  //    finalmente Attachment.url punta a storage reale.
  return NextResponse.json({
    id: item.id,
    nome: file.name,
    tipo: file.type,
    dimensione: item.size,
    url: item.webUrl,               // deep link SharePoint
    dataCaricamento: new Date().toISOString(),
    caricatoDa: user.email,
  }, { status: 201 });
}

/**
 * src/app/api/richieste/[id]/documenti/route.ts — GET: elenco documenti del fascicolo.
 * Query sulla lista SharePoint filtrando la colonna indicizzata tsRichiestaId
 * (indicizzazione obbligatoria: evita il list view threshold 5000 e il fallimento del $filter).
 * Output: Attachment[] coerente con src/types/index.ts:359-367, consumabile da
 * RequestManager.tsx / Dashboard.tsx senza cambiare il tipo.
 */
import { NextRequest, NextResponse } from 'next/server';
import { GRAPH, SP_SITE_ID, SP_LIST_ID, graphFetch } from '@/lib/graph/graphClient';
import { verifyEntraToken } from '@/lib/graph/verifyToken';
import type { Attachment } from '@/types';

export async function GET(req: NextRequest, { params }: { params: { id: string } }) {
  const user = await verifyEntraToken(req.headers.get('authorization'));
  if (!user) return NextResponse.json({ error: 'Non autorizzato' }, { status: 401 });

  const url =
    `${GRAPH}/sites/${SP_SITE_ID}/lists/${SP_LIST_ID}/items` +
    `?$expand=fields($select=tsTipoDocumento,tsNumeroProgressivo,tsCaricatoDa),driveItem` +
    `&$filter=fields/tsRichiestaId eq '${encodeURIComponent(params.id)}'`;

  const res = await graphFetch(url, {
    // richiesto da Graph per filtri su colonne non indicizzate; innocuo se la colonna e' indicizzata
    headers: { Prefer: 'HonorNonIndexedQueriesWarningMayFailRandomly' },
  });
  if (!res.ok) return NextResponse.json({ error: await res.text() }, { status: res.status });

  const data = await res.json();
  const allegati: (Attachment & { tipoDocumento?: string })[] = (data.value ?? [])
    .filter((it: any) => it.driveItem?.file) // esclude le cartelle
    .map((it: any) => ({
      id: it.driveItem.id,
      nome: it.driveItem.name,
      tipo: it.driveItem.file.mimeType ?? '',
      dimensione: it.driveItem.size ?? 0,
      url: it.driveItem.webUrl,                       // Attachment.url = link reale SPO
      dataCaricamento: new Date(it.driveItem.createdDateTime),
      caricatoDa: it.fields?.tsCaricatoDa ?? '',
      tipoDocumento: it.fields?.tsTipoDocumento,
    }));

  return NextResponse.json(allegati);
}

/**
 * src/lib/documentLinks.ts — costruzione link profondi (usabile anche client-side: nessun segreto).
 * Uso: Dashboard.tsx (riga richiesta -> pulsante "Fascicolo") e RequestManager.tsx
 * (dettaglio richiesta -> lista allegati con <a href={att.url}>).
 */

/** Base sito: ASSUNZIONE DA VERIFICARE. Esporre via env pubblica (e' un URL, non un segreto). */
const SP_SITE_URL =
  process.env.NEXT_PUBLIC_SP_SITE_URL ??
  'https://toscananordovest.sharepoint.com/sites/DipartimentoTecnico';
const SP_LIBRARY_PATH = process.env.NEXT_PUBLIC_SP_LIBRARY_PATH ?? 'FascicoliRichiesteTS';

/** Link profondo alla CARTELLA fascicolo di una richiesta (vista libreria filtrata sulla cartella). */
export function buildFascicoloLink(numeroProgressivo: string): string {
  const folderPath = `/sites/DipartimentoTecnico/${SP_LIBRARY_PATH}/${numeroProgressivo}`;
  return `${SP_SITE_URL}/${SP_LIBRARY_PATH}/Forms/AllItems.aspx?id=${encodeURIComponent(folderPath)}`;
}

/** Link profondo al SINGOLO documento: usare sempre driveItem.webUrl restituito dalle API
 *  (gia' presente in Attachment.url dopo la Fase 3) — apre Office online / anteprima PDF. */
export function buildDocumentLink(att: { url: string }): string {
  return att.url;
}

/** Vista libreria filtrata per metadato (es. tutti i verbali CommAz di una UO). */
export function buildFilteredViewLink(colonna: string, valore: string): string {
  return `${SP_SITE_URL}/${SP_LIBRARY_PATH}/Forms/AllItems.aspx` +
    `?useFiltersInViewXml=1&FilterField1=${encodeURIComponent(colonna)}` +
    `&FilterValue1=${encodeURIComponent(valore)}&FilterType1=Text`;
}

