/**
 * src/app/api/reports/quarterly/route.ts — POST: genera report trimestrale e lo deposita in SharePoint.
 * Riusa generateQuarterlyReport/formatReportAsText (src/lib/reports.ts:17,265) e valorizza
 * QuarterlyReport.fileReportPDF (src/types/index.ts:426) con l'URL SPO reale.
 * PDF via pdf-lib / @react-pdf/renderer, Excel via exceljs (dipendenze da aggiungere) —
 * in alternativa la generazione PDF puo' restare al flusso Power Automate (opzione C).
 */
import { NextRequest, NextResponse } from 'next/server';
import { GRAPH, SP_SITE_ID, SP_DRIVE_ID, graphFetch } from '@/lib/graph/graphClient';
import { verifyEntraToken } from '@/lib/graph/verifyToken';

export async function POST(req: NextRequest) {
  const user = await verifyEntraToken(req.headers.get('authorization'));
  if (!user) return NextResponse.json({ error: 'Non autorizzato' }, { status: 401 });

  const { anno, trimestre, pdfBase64, xlsxBase64 } = await req.json();
  const results: Record<string, string> = {};

  for (const [ext, b64] of [['pdf', pdfBase64], ['xlsx', xlsxBase64]] as const) {
    if (!b64) continue;
    const name = `Report_TS_${anno}_Q${trimestre}.${ext}`;
    const up = await graphFetch(
      `${GRAPH}/sites/${SP_SITE_ID}/drives/${SP_DRIVE_ID}/root:/Report Trimestrali/${name}:/content`,
      { method: 'PUT', headers: { 'Content-Type': 'application/octet-stream' },
        body: Buffer.from(b64, 'base64') },
    );
    if (!up.ok) return NextResponse.json({ error: await up.text() }, { status: up.status });
    const item = await up.json();
    await graphFetch(`${GRAPH}/sites/${SP_SITE_ID}/drives/${SP_DRIVE_ID}/items/${item.id}/listItem/fields`, {
      method: 'PATCH', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ tsTipoDocumento: 'REPORT_TRIMESTRALE', tsAnno: anno,
                             tsTrimestre: trimestre, tsCaricatoDa: user.email }),
    });
    results[ext] = item.webUrl; // -> QuarterlyReport.fileReportPDF
  }
  return NextResponse.json(results, { status: 201 });
}
